def write(lang, table):
    path = os.path.join(ROOT, 'src/i18n/%s.json' % lang)
    old = json.load(open(path, encoding='utf8')) if os.path.exists(path) else {}
    out = dict(old)
    for i, tr in table.items():
        out[EN[i]] = tr
    json.dump(out, open(path, 'w', encoding='utf8'), ensure_ascii=False, indent=1, sort_keys=True)
    print(lang, len(out))


write('ru', RU)
write('kk', KK)
